INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0001.xhtml', 'OEBPS/Text/part0002.xhtml', 4, 0, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0002.xhtml', '译者序 特立独行的人从来不会徒劳伤悲', '', 'np_4');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0002.xhtml', 'OEBPS/Text/part0003.xhtml', 5, 0, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0003.xhtml', 'CHAPTER1 置身于阳光与苦难之间', '', 'np_5');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0003.xhtml', 'OEBPS/Text/part0004.xhtml', 6, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0004.xhtml', '嘲讽蜷缩于事物深处，我侧耳倾听', 'np_5', 'np_6');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0004.xhtml', 'OEBPS/Text/part0005.xhtml', 7, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0005.xhtml', '夜晚是绝望而温柔的孤独', 'np_5', 'np_7');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0005.xhtml', 'OEBPS/Text/part0006.xhtml', 8, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0006.xhtml', '生活就是立体的世界，有正有反', 'np_5', 'np_8');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0006.xhtml', 'OEBPS/Text/part0007.xhtml', 9, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0007.xhtml', '无论繁华与清远，我都深爱这个世界', 'np_5', 'np_9');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0007.xhtml', 'OEBPS/Text/part0008.xhtml', 10, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0008.xhtml', '只要愿意，终可以潜踪遁迹', 'np_5', 'np_10');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0008.xhtml', 'OEBPS/Text/part0009.xhtml', 11, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0009.xhtml', '没有生存的痛苦，就不会热爱生活', 'np_5', 'np_11');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0009.xhtml', 'OEBPS/Text/part0010.xhtml', 12, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0010.xhtml', '即使是为了逃避，也不要假装热爱生活', 'np_5', 'np_12');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0010.xhtml', 'OEBPS/Text/part0011.xhtml', 13, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0011.xhtml', '撕裂你的内心，才能看到潜藏起来的真正生活', 'np_5', 'np_13');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0011.xhtml', 'OEBPS/Text/part0012.xhtml', 14, 1, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0012.xhtml', '面对阳光，你就永远看不到阴影', 'np_5', 'np_14');
INSERT INTO `contents` VALUES ('2466e3857b394a162ff1a69f66618147', 'x_Section0002_0012.xhtml', 'OEBPS/Text/part0013.xhtml', 15, 0, 'https://book.youbaobao.xyz/admin-upload-ebook/unzip/2466e3857b394a162ff1a69f66618147/OEBPS/Text/part0013.xhtml', 'CHAPTER2 使人成熟的不是岁月，而是经历', '', 'np_15');
